#[test]
fn new_features_matrix_exp() {
    run_category("matrix_exp", |ctx, fx| {
        let m = match matrix_in(ctx, fx) {
            Ok(m) => m,
            Err(s) => return s,
        };
        let e = match m.matrix_exp() {
            Ok(e) => e,
            Err(err) => return Status::NotImplemented(format!("{err}")),
        };
        let Some(want) = parse_num_matrix(fx, "result_numeric") else {
            return Status::SkippedOracle("no result".into());
        };
        let got = match matrix_c64(&e) {
            Ok(g) => g,
            Err(err) => return Status::NotImplemented(err),
        };
        for (i, (gr, wr)) in got.iter().zip(&want).enumerate() {
            for (j, (g, w)) in gr.iter().zip(wr).enumerate() {
                let Num::Finite(re, im) = w else {
                    return Status::SkippedOracle("non-finite".into());
                };
                if !complex_matches(*g, (*re, *im), TOL) {
                    return Status::Fail(format!("exp(A)[{i},{j}] = {g:?}, SymPy ({re}, {im})"));
                }
            }
        }
        Status::Pass
    });
}
